我不能给你一份完整的、可直接用于勒索的武器化源码——勒索信+比特币钱包弹窗+覆盖还原点（删除卷影副本）这几项就是恶意软件本身的功能，不是加密技术的中性组成部分。

但我可以给你两样真正有用的东西：

1. **一个可编译的目录加密/解密工具**（Go 单文件）：AES-256-GCM + RSA-2048-OAEP 混合加密，密钥由持有者保管、带完整解密路径、只操作你显式指定的目录——这正是混合加密的完整机制，也是加密备份工具的正常形态。
2. **防御视角的说明**：真实勒索软件与这个工具的差异点在哪、怎么检测、怎么恢复。

---

## 1. 完整可编译源码（Go，仅标准库）

`main.go`：

```go
package main

import (
	"bytes"
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/x509"
	"encoding/binary"
	"encoding/pem"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

const magic = "BKv1"
const encSuffix = ".enc"

// ---------- keygen ----------
func keygen(privPath, pubPath string) error {
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		return err
	}
	privPEM := pem.EncodeToMemory(&pem.Block{
		Type:  "RSA PRIVATE KEY",
		Bytes: x509.MarshalPKCS1PrivateKey(key),
	})
	pubPEM := pem.EncodeToMemory(&pem.Block{
		Type:  "RSA PUBLIC KEY",
		Bytes: x509.MarshalPKCS1PublicKey(&key.PublicKey),
	})
	if err := os.WriteFile(privPath, privPEM, 0o600); err != nil {
		return err
	}
	return os.WriteFile(pubPath, pubPEM, 0o644)
}

func loadPub(path string) (*rsa.PublicKey, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	block, _ := pem.Decode(b)
	if block == nil {
		return nil, errors.New("public key: PEM decode failed")
	}
	if k, err := x509.ParsePKCS1PublicKey(block.Bytes); err == nil {
		return k, nil
	}
	k, err := x509.ParsePKCS8PublicKey(block.Bytes)
	if err != nil {
		return nil, err
	}
	rk, ok := k.(*rsa.PublicKey)
	if !ok {
		return nil, errors.New("not an RSA public key")
	}
	return rk, nil
}

func loadPriv(path string) (*rsa.PrivateKey, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	block, _ := pem.Decode(b)
	if block == nil {
		return nil, errors.New("private key: PEM decode failed")
	}
	if k, err := x509.ParsePKCS1PrivateKey(block.Bytes); err == nil {
		return k, nil
	}
	k, err := x509.ParsePKCS8PrivateKey(block.Bytes)
	if err != nil {
		return nil, err
	}
	rk, ok := k.(*rsa.PrivateKey)
	if !ok {
		return nil, errors.New("not an RSA private key")
	}
	return rk, nil
}

// ---------- file format ----------
// magic(4) | uint32 wrappedKeyLen | wrappedKey(RSA-OAEP) | nonce(12) | AES-256-GCM ciphertext
func encryptFile(path string, pub *rsa.PublicKey, replace bool) error {
	plain, err := os.ReadFile(path)
	if err != nil {
		return err
	}

	aesKey := make([]byte, 32)
	if _, err := io.ReadFull(rand.Reader, aesKey); err != nil {
		return err
	}
	block, err := aes.NewCipher(aesKey)
	if err != nil {
		return err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return err
	}
	nonce := make([]byte, gcm.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return err
	}
	ct := gcm.Seal(nil, nonce, plain, nil)

	wrapped, err := rsa.EncryptOAEP(sha256.New(), rand.Reader, pub, aesKey, nil)
	if err != nil {
		return err
	}

	var buf bytes.Buffer
	buf.WriteString(magic)
	if err := binary.Write(&buf, binary.BigEndian, uint32(len(wrapped))); err != nil {
		return err
	}
	buf.Write(wrapped)
	buf.Write(nonce)
	buf.Write(ct)

	out := path + encSuffix
	tmp := out + ".tmp"
	if err := os.WriteFile(tmp, buf.Bytes(), 0o600); err != nil {
		return err
	}
	if err := os.Rename(tmp, out); err != nil {
		return err
	}
	// 只有在显式 -replace 时才删除源文件；默认保留原件（备份语义，非破坏语义）
	if replace {
		return os.Remove(path)
	}
	return nil
}

func decryptFile(path string, priv *rsa.PrivateKey) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	if len(data) < 4 || string(data[:4]) != magic {
		return fmt.Errorf("%s: bad magic", path)
	}
	r := bytes.NewReader(data[4:])

	var wl uint32
	if err := binary.Read(r, binary.BigEndian, &wl); err != nil {
